function VaultGate({done}:{done:(u?:TeamUser|null)=>void}){const[existing,setExisting]=useState<boolean|null>(null),[p,setP]=useState(''),[m,setM]=useState('');useEffect(()=>{localVault.hasVault().then(setExisting).catch(e=>{setM(e?.message||'Storage مرورگر در دسترس نیست');setExisting(false)})},[]);if(existing===null)return<div className="loading">در حال آماده‌سازی Vault…</div>;return<main className="login"><section><div className="brandmark"><ShieldCheck size={28}/></div><h1>کوله‌پشتی</h1><p>مرکز کنترل کیفیت مکالمات فارسی</p><div className="login-copy">{existing?'Passphrase محلی Vault را وارد کنید.':'برای این مرورگر یک Vault رمزگذاری‌شده بسازید.'}</div><input type="password" placeholder="Passphrase حداقل ۱۲ کاراکتر" value={p} onChange={e=>setP(e.target.value)}/><button className="primary xl" onClick={async()=>{try{existing?await localVault.unlockVault(p):await localVault.initVault(p);done(null)}catch(e:any){setM(e.message||'خطا')}}}>{existing?'ورود به کوله‌پشتی':'ساخت Vault و ورود'}</button><small>Passphrase و فایل صوتی به هیچ سروری ارسال نمی‌شوند.</small>{m&&<b className="err">{m}</b>}</section></main>}

function TeamGate({done}:{done:(u?:TeamUser|null)=>void}){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[m,setM]=useState(''),[checking,setChecking]=useState(true);useEffect(()=>{session().then(u=>{if(u)done(u);else setChecking(false)}).catch(()=>setChecking(false))},[]);if(checking)return<div className="loading">در حال بررسی نشست تیم…</div>;return<main className="login"><section><div className="brandmark"><Users size={28}/></div><h1>کوله‌پشتی تیم QC</h1><p>ورود امن به پایگاه داده مشترک</p><div className="login-copy">مکالمه و STT روی مرورگر پردازش می‌شود؛ داده QC مجاز در PostgreSQL مرکزی ذخیره خواهد شد.</div><input inputMode="email" placeholder="ایمیل سازمانی" value={email} onChange={e=>setEmail(e.target.value)}/><input type="password" placeholder="رمز عبور" value={password} onChange={e=>setPassword(e.target.value)}/><button className="primary xl" onClick={async()=>{try{setM('');done(await login(email,password))}catch(e:any){setM(e.message==='invalid_credentials'?'ایمیل یا رمز عبور نادرست است.':e.message||'خطای ورود')}}}>ورود به فضای تیم</button><small>Session امن HttpOnly · RBAC · Audit</small>{m&&<b className="err">{m}</b>}</section></main>}
function AccessGate({done}:{done:(u?:TeamUser|null)=>void}){return isTeamMode()?<TeamGate done={done}/>:<VaultGate done={done}/>} 

function Sparkline({rows}:{rows:{label:string;avg:number;count:number}[]}){const vals=rows.map(x=>x.avg),max=Math.max(100,...vals),min=0,w=640,h=180,p=20;const pts=rows.map((x,i)=>{const xx=p+i*((w-p*2)/Math.max(1,rows.length-1)),yy=h-p-((x.avg-min)/(max-min||1))*(h-p*2);return[xx,yy]});return<div className="chartbox"><svg viewBox={`0 0 ${w} ${h}`} role="img" aria-label="روند امتیاز"><line x1="20" y1="160" x2="620" y2="160" className="gridline"/><line x1="20" y1="90" x2="620" y2="90" className="gridline"/><line x1="20" y1="20" x2="620" y2="20" className="gridline"/><polyline fill="none" className="trendline" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" points={pts.map(x=>x.join(',')).join(' ')}/>{pts.map((x,i)=><circle key={i} cx={x[0]} cy={x[1]} r="4.5" className="trenddot"><title>{rows[i].label}: {rows[i].avg||'بدون داده'}</title></circle>)}</svg><div className="axislabels">{rows.map(x=><span key={x.label}>{x.label}</span>)}</div></div>}

function RiskDonut({r}:{r:{low:number;medium:number;high:number;critical:number}}){const total=r.low+r.medium+r.high+r.critical;if(!total)return<div className="empty compact">داده کافی وجود ندارد.</div>;const a=r.low/total*360,b=a+r.medium/total*360,c=b+r.high/total*360;return<div className="riskwrap"><div className="donut" style={{background:`conic-gradient(var(--good) 0 ${a}deg,var(--mid) ${a}deg ${b}deg,var(--high) ${b}deg ${c}deg,var(--critical) ${c}deg 360deg)`}}><div><b>{fa.format(total)}</b><span>پرونده</span></div></div><div className="legend"><span><i className="low"/>کم‌ریسک <b>{r.low}</b></span><span><i className="medium"/>متوسط <b>{r.medium}</b></span><span><i className="high"/>بالا <b>{r.high}</b></span><span><i className="critical"/>بحرانی <b>{r.critical}</b></span></div></div>}

function Pareto({rows}:{rows:{id:string;label:string;count:number;critical:boolean}[]}){const max=Math.max(1,...rows.map(x=>x.count));return<div className="pareto">{rows.length?rows.map(x=><div key={x.id}><div className="pareto-head"><span><b>{x.id}</b> {x.label}{x.critical&&<em>Critical</em>}</span><strong>{fa.format(x.count)}</strong></div><div className="bar"><i style={{width:`${x.count/max*100}%`}}/></div></div>):<div className="empty compact">هنوز خطای تکرارشونده‌ای ثبت نشده است.</div>}</div>}

function Calibration({onRun,gold}:{onRun:(m:File|null,f:FileList|null)=>void;gold:any}){const[m,setM]=useState<File|null>(null),[f,setF]=useState<FileList|null>(null);const g=gold?.gate||{},x=gold?.metrics||{};return<article className="panel"><div className="panel-title"><div><h3>Gold Calibration</h3><p>Smoke ≥۲۰ و Production ≥۵۰ فایل adjudicated.</p></div><ShieldCheck/></div><label>Manifest JSON<input type="file" accept=".json" onChange={e=>setM(e.target.files?.[0]||null)}/></label><label>فایل‌های Gold<input type="file" multiple accept="audio/*" onChange={e=>setF(e.target.files)}/></label><button className="primary" onClick={()=>onRun(m,f)}>اجرای Benchmark محلی</button>{gold&&<><div className="score-row"><div><span>WER</span><b>{fa.format(x.wer??0)}%</b></div><div><span>RTF</span><b>{fa.format(x.rtf??0)}</b></div><div><span>Cases</span><b>{fa.format(x.cases??0)}</b></div></div><div className="gategrid"><span className={g.smokeCases?'pass':'fail'}>Smoke ≥20</span><span className={g.productionCases?'pass':'fail'}>Production ≥50</span><span className={g.criticalRecall?'pass':'fail'}>Critical Recall</span><span className={g.numberRecall?'pass':'fail'}>Number Recall</span><span className={g.negationRecall?'pass':'fail'}>Negation</span><span className={g.silence?'pass':'fail'}>Silence</span></div></>}</article>}

