<label>PVQ-030 Expected Brand<select value={physWf.expectedBrand} onChange={e=>setPhysWf({...physWf,expectedBrand:e.target.value as any})}><option value="unknown">نامشخص</option><option value="drsaina">دکترساینا</option><option value="robra">روبرا</option><option value="doctor_doctor">دکتر دکتر</option><option value="homca">هومکا</option><option value="man">مان</option><option value="not_applicable">نامرتبط</option></select></label>
